 ask viewers to read and stick to the DW netiquette policy on our channel: https://p.dw.com/p/MF1G","thumbnail":"https://i.ytimg.com/vi/w6jdF6e0hLc/maxresdefault.jpg","category":"Documentaries","city":"","country":"","channel":"DW Documentary","channelTitle":"DW Documentary","channelId":"UCW39zufHfsuGgpLviKh297Q","badge":"DOCUMENTARY","publishedAt":"2024-10-23T16:01:05Z","viewCount":2406412,"durationSeconds":2546,"admission":{"version":3,"status":"channel-candidate","source":"channel-archive","mode":"DOCUMENTARIES"}}',1);
